// src/component/WDBaseAllocationTab.js

import React, { useState, useMemo, useEffect } from 'react';

// --- Icon Components (no changes needed) ---
const InfoIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="16" x2="12" y2="12"></line><line x1="12" y1="8" x2="12.01" y2="8"></line></svg>
);
const AddIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line></svg>
);
const EditIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7"></path><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z"></path></svg>
);
const DeleteIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6"></polyline><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"></path><line x1="10" y1="11" x2="10" y2="17"></line><line x1="14" y1="11" x2="14" y2="17"></line></svg>
);

export default function WDBaseAllocationTab({ subject }) {
    const { subjectCoordinator = "N/A", totalAvailableWorkload = 0 } = subject || {};

    // State now stores allocation as a string to handle user input like ".", "-", or "abc"
    const [otherStaffAllocations, setOtherStaffAllocations] = useState([]);

    // State for validation messages
    const [totalErrorMessage, setTotalErrorMessage] = useState('');
    const [rowErrors, setRowErrors] = useState({});

    // --- Memoized Calculation for Delegated Workload ---
    // This now parses the string allocation input into a number for calculation
    const totalDelegatedWorkload = useMemo(() => {
        return otherStaffAllocations.reduce((total, item) => {
            const numericAllocation = parseFloat(item.allocation);
            // Only add valid, positive numbers to the sum
            if (!isNaN(numericAllocation) && numericAllocation > 0) {
                return total + (numericAllocation / 100);
            }
            return total;
        }, 0);
    }, [otherStaffAllocations]);

    const coordinatorAllocation = useMemo(() => {
        const remaining = totalAvailableWorkload - totalDelegatedWorkload;
        return remaining >= 0 ? remaining : 0;
    }, [totalAvailableWorkload, totalDelegatedWorkload]);

    // --- Validation Effect ---
    // This effect runs whenever allocations change to validate all test cases
    useEffect(() => {
        const newRowErrors = {};
        let currentDelegatedSum = 0;

        otherStaffAllocations.forEach(row => {
            const allocValue = parseFloat(row.allocation);

            if (row.allocation && isNaN(allocValue)) {
                newRowErrors[row.id] = 'Allocation must be a numeric value.';
            } else if (allocValue < 0) {
                newRowErrors[row.id] = 'Allocation percentage cannot be negative.';
            } else if (allocValue > 0 && (!row.task.trim() || !row.staffMember.trim())) {
                newRowErrors[row.id] = 'Task and Staff Member are required for allocations.';
            }

            if (!isNaN(allocValue) && allocValue > 0) {
                currentDelegatedSum += allocValue / 100;
            }
        });

        setRowErrors(newRowErrors);

        // Check for total allocation exceeding available workload
        if (currentDelegatedSum > totalAvailableWorkload) {
            setTotalErrorMessage("Total allocation to other staff cannot exceed the available workload.");
        } else {
            setTotalErrorMessage('');
        }
    }, [otherStaffAllocations, totalAvailableWorkload]);

    // --- Event Handlers ---
    const handleAddRow = () => {
        const newRow = {
            id: Date.now(),
            task: '',
            staffMember: '',
            allocation: '', // Start with an empty string for the input field
        };
        setOtherStaffAllocations(prev => [...prev, newRow]);
    };

    const handleDeleteRow = (id) => {
        setOtherStaffAllocations(prev => prev.filter(row => row.id !== id));
        setRowErrors(prev => {
            const newErrors = { ...prev };
            delete newErrors[id];
            return newErrors;
        });
    };

    const handleInputChange = (id, field, value) => {
        setOtherStaffAllocations(prev =>
            prev.map(row => (row.id === id ? { ...row, [field]: value } : row))
        );
    };

    const formatAsPercent = (value) => `${(value * 100).toFixed(1)}%`;

    return (
        <div style={styles.tabContentContainer}>
            <div style={styles.tabHeader}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                    <h3 style={styles.tabTitle}>Base Allocation</h3>
                    <span title="Distribute workload to teaching staff." style={{ color: '#6c757d', cursor: 'pointer' }}><InfoIcon /></span>
                </div>
                <button style={styles.addButton} onClick={handleAddRow}><AddIcon /> Add</button>
            </div>

            <table style={styles.table}>
                <thead>
                    <tr style={styles.tableHeaderRow}>
                        <th style={{ ...styles.tableHeaderCell, width: '10%' }}>Actions</th>
                        <th style={styles.tableHeaderCell}>Task</th>
                        <th style={{ ...styles.tableHeaderCell, width: '25%' }}>Staff Member</th>
                        <th style={{ ...styles.tableHeaderCell, width: '20%', textAlign: 'right' }}>Allocation</th>
                    </tr>
                </thead>
                <tbody>
                    {otherStaffAllocations.map((row) => (
                        <React.Fragment key={row.id}>
                            <tr style={styles.tableRow}>
                                <td style={styles.tableCell}>
                                    <div style={{ display: 'flex', gap: '1rem' }}>
                                        <button style={styles.iconButton} title="Edit"><EditIcon /></button>
                                        <button style={styles.iconButton} title="Delete" onClick={() => handleDeleteRow(row.id)}><DeleteIcon /></button>
                                    </div>
                                </td>
                                <td style={styles.tableCell}>
                                    <input type="text" style={styles.inputField} value={row.task} onChange={(e) => handleInputChange(row.id, 'task', e.target.value)} placeholder="Enter task description" />
                                </td>
                                <td style={styles.tableCell}>
                                     <input type="text" style={styles.inputField} value={row.staffMember} onChange={(e) => handleInputChange(row.id, 'staffMember', e.target.value)} placeholder="Enter staff name" />
                                </td>
                                <td style={{ ...styles.tableCell, textAlign: 'right' }}>
                                    <div style={styles.allocationInputContainer}>
                                        <input type="text" style={{...styles.inputField, textAlign: 'right', borderColor: rowErrors[row.id] ? '#dc3545' : '#ced4da' }} value={row.allocation} onChange={(e) => handleInputChange(row.id, 'allocation', e.target.value)} />
                                        <span>%</span>
                                    </div>
                                </td>
                            </tr>
                            {/* Row for displaying validation error */}
                            {rowErrors[row.id] && (
                                <tr style={styles.errorRow}>
                                    <td></td>
                                    <td colSpan="3" style={styles.errorCell}>{rowErrors[row.id]}</td>
                                </tr>
                            )}
                        </React.Fragment>
                    ))}
                    {/* Read-only row for Subject Coordinator */}
                    <tr style={styles.tableRow}>
                        <td style={styles.tableCell}></td>
                        <td style={styles.tableCell}>
                            Allocation to Subject Coordinator: <strong>{subjectCoordinator}</strong>
                        </td>
                        <td style={styles.tableCell}></td>
                        <td style={{ ...styles.tableCell, textAlign: 'right', fontWeight: 'bold' }}>
                            {formatAsPercent(coordinatorAllocation)}
                        </td>
                    </tr>
                </tbody>
            </table>

            {totalErrorMessage && <div style={styles.totalErrorText}>{totalErrorMessage}</div>}

            <footer style={styles.tabFooter}>
                <button style={styles.button('primary')}>Save</button>
            </footer>
        </div>
    );
}

// --- Styles ---
const styles = {
    tabContentContainer: { padding: '2rem', backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #dee2e6', marginTop: '-1px' },
    tabHeader: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1.5rem' },
    tabTitle: { margin: 0, color: '#343a40', fontSize: '1.25rem' },
    addButton: { padding: '0.5rem 1rem', fontSize: '0.9rem', borderRadius: '6px', border: 'none', cursor: 'pointer', fontWeight: '500', backgroundColor: '#0d0d0d', color: 'white', display: 'flex', alignItems: 'center', gap: '0.5rem' },
    table: { width: '100%', borderCollapse: 'collapse' },
    tableHeaderRow: { borderBottom: '2px solid #343a40' },
    tableHeaderCell: { padding: '0.75rem 0.5rem', textAlign: 'left', color: '#495057', fontWeight: '600', fontSize: '0.9rem' },
    tableRow: { borderBottom: '1px solid #dee2e6' },
    errorRow: { borderBottom: '1px solid #dee2e6' },
    errorCell: { padding: '0 0.5rem 0.75rem 0.5rem', color: '#dc3545', fontSize: '0.8rem' },
    tableCell: { padding: '0.75rem 0.5rem', color: '#343a40', verticalAlign: 'middle' },
    iconButton: { background: 'none', border: 'none', cursor: 'pointer', padding: '0.25rem', color: '#495057' },
    inputField: { width: '100%', padding: '0.5rem', border: '1px solid #ced4da', borderRadius: '4px', fontSize: '0.9rem', boxSizing: 'border-box' },
    allocationInputContainer: { display: 'flex', alignItems: 'center', justifyContent: 'flex-end', gap: '0.5rem' },
    totalErrorText: { color: '#dc3545', marginTop: '1rem', fontSize: '0.9rem', fontWeight: '500' },
    tabFooter: { display: 'flex', justifyContent: 'flex-start', marginTop: '2rem', borderTop: '1px solid #e9ecef', paddingTop: '1.5rem' },
    button: (variant = 'primary') => ({ padding: '0.6rem 1.2rem', fontSize: '1rem', borderRadius: '6px', border: 'none', cursor: 'pointer', fontWeight: '500', transition: 'background-color 0.2s', backgroundColor: variant === 'primary' ? '#0d0d0d' : '#6c757d', color: 'white' }),
};
